def the_release(case, data):
    """F1 — Deut 15:1-3 — THE LINE release_law_declared writing debt_release_owed (a STATUS whose value is THE RELEASE DATE a clock datum by CALL to the cycle — the seventh year's end, one calendar for the whole world) and exaction_barred (a BLOCK — 'he shall not exact'); the onset, the territory, the object, the manner, the prozbul PARAMETERS from the answer sheet (Mishnah Sheviit 10); the foreigner by CALL to yovel.interest_scope"""
    del P_[:]
    ask = case['ask']
