    if ask == 'the_base_thought':
        ink('15:9', '"BEWARE lest there be a BASE thought in your heart, saying: the seventh year, the year of release, draws near" — "beware lest" at its sixth seat in the book of nine %s; "base" (בליעל) the Torah\'s TWO %s; "the seventh year, the year of release" %s (one seat); the imperative "beware" the chapter\'s one %s; the ordinal [7] at 15:9 %s' % (P('השמר', 'לך', 'פן', books=DT), BASE, P('שנת', 'השבע', 'שנת', 'השמטה'), [(x, m) for v in (9,) for x, m in by[('Deut', 15, v)] if m and re.match(r'^HV.?.?v', m)], ORDS[9]))
        move('the Sifrei 117:1-3 (read whole at the reading); Gittin 36a:11 (read whole at the docket); cold_run_seducers (CALL — THE TRANSFER taught by the Sifrei 117:3, labeled) — SE.DATA the_seducers_parameters[belial] = %r; SE.the_city_heard_of_the_inquiry_and_the_sword(%s) = %s' % (SE_BELIAL_PARAM, _se_belial, str(V(SE_BELIAL))[:70]), "'BASE' WITHOUT A YOKE (117:1 — E30, checked in MIDDOT.md: the word's parts 'without a yoke' — the yoke of heaven thrown off); READ AS IDOLATRY BY I2 WITH 13:14 (117:3, checked in MIDDOT.md — 'base' is said here and 'base' is said of the sons of Belial who lead a city astray: whoever shuts his eyes from charity is as an idolater — THE TRANSFER taught by the Sifrei, the exemplar 13:14's sons of Belial, the seducers' cell by CALL: a labeled edge); 'beware' and 'lest' two prohibitions (117:2); Hillel's reason for the prozbul this verse (Gittin 36a:11); Onkelos 'in wickedness' (ברשע — 13:14's sons of Belial rendered by the same word)")
        dat('THE WRITE base_thought_barred — a BLOCK on israel_people at the counter\'s day (DG2); the transfer\'s edge release_firstborn -> seducers labeled with its teacher (the Sifrei 117:3); the exam\'s person the one who refuses a loan because the seventh year is near — barred from it')
        return out("the base thought (15:9) — 'beware lest a base thought': 'base' without a yoke (the Sifrei 117:1 — E30), read as idolatry by I2 with 13:14's sons of Belial (117:3 — the TRANSFER taught by the Sifrei, seducers by CALL, labeled); Hillel's reason for the prozbul (Gittin 36a:11): THE WRITE base_thought_barred, a BLOCK on Israel at the chapter's own day; the one who refuses a loan because the seventh year is near barred from it", ['base_thought_barred'])
    if ask == 'the_cry_and_the_sin':
        ink('15:9', '"and he CRY to the LORD against you, and it BE SIN in you" — "and it be sin in you" THREE in the book %s (the needy\'s cry, the vow 23:22, the hireling\'s cry 24:15); 24:15\'s clause %s, the shared run %d; Exodus 22:22\'s doubled cry %s; the Name alone at 15:9 (not "your God") %s' % (SIN_IN_YOU, words('Deut', 24, 15)[-6:], TWIN['15:9 vs 24:15'], words('Exod', 22, 22)[6:12], [v for v in range(1, 24) if 'יהוה' in W15(v) and not any(W15(v)[i:i + 2] == ['יהוה', 'אלהיך'] for i in range(len(W15(v)) - 1))]))
        move('the Sifrei 117:5 with 279:4 word for word (read whole at the reading); cold_run_ordinances (CALL) — OR.loan(creditor_manner) = %s; the one database: cry_heard on israel_people before this daemon\'s lines %s, bears_sin %s' % (V(OR_MANNER), REUSE_SCAN[1] if REUSE_SCAN else None, REUSE_SCAN[2] if REUSE_SCAN else None), "THE CRY A HASTENER AND THE SIN UNCONDITIONAL — 'and he cry to the LORD against you': might it be a commandment not to cry? 'and it be sin in you' — whether he cries or not; 'and he cry' — I hasten to punish through the one who cries more than through the one who does not (117:5; 279:4 the hireling's cry WORD FOR WORD — 24:15 seven tokens in order); cry_heard REUSED (the HEAVEN entry of the pledged poor man's cry, Exodus 22:22-23's — the ordinances' line on the tape, cry_went_up Exod 2:23 the cry's first seat) and bears_sin REUSED (the STATUS 'it be sin in you' — the divine ledger; the running world held none): second entries on Israel at the chapter's own day")
        dat('THE TWO REUSES cry_heard and bears_sin — entries on israel_people on the line hand_opening_commanded (DG2 — the before-counts read from the one database by source: cry_heard ONE, bears_sin NONE); the readback row 15:9 SUPPLIED with base_thought_barred, the cry by kind (cry_went_up Exod 2:23); the exam\'s person the needy who cries to the LORD against the shut hand — accepted, the sin in the refuser whether he cries or not')
        return out("the cry and the sin (15:9) — 'and he cry to the LORD against you and it be sin in you': the cry a hastener, the sin unconditional (the Sifrei 117:5 with 279:4 word for word — 24:15's hireling seven tokens in order): cry_heard and bears_sin REUSED — entries on Israel at the chapter's own day (Exodus 22:22's cry the first seat); the needy who cries against the shut hand accepted", ['accepted'])
    if ask == 'the_secret_gift':
        ink('15:10', '"GIVE, YOU SHALL GIVE him, and your heart shall not grieve when you give him" — "give, you shall give" %s (Jephthah\'s vow the other seat); "your heart grieved" %s (Elkanah\'s to Hannah); "give" eight tokens in six verses %s' % (P('נתון', 'תתן'), P('ירע', 'לבבך'), {v: [x for x in W15(v) if x in ('תתן', 'נתן', 'ונתתה', 'בתתך', 'נתון', 'תתנו')] for v in range(1, 24) if any(x in ('תתן', 'נתן', 'ונתתה', 'בתתך', 'נתון', 'תתנו') for x in W15(v))}))
        move('the Sifrei 117:6-8 (read whole at the reading); Mishnah Shekalim 5:6 (inside the spine and at the docket); Ketubot 67b:12-18 (read whole at the docket)', "THE SECRET GIFT — 'and your heart shall not grieve when you give him': Mishnah Shekalim 5:6 inside the spine — THE CHAMBER OF THE SILENT, where the sin-fearing put in secret and the poor of good family are sustained in secret (117:7); THE FOUR GRADES OF THE GIVER (117:8 — gives and wishes others to give, gives and wishes others not to, does not give and wishes others to, neither: a DATA row); the secret givers of Ketubot 67b:12-18 (Mar Ukva's coin in the door's socket)")
        dat('the secret gift a DATA row (the_secret_gift — Shekalim 5:6\'s chamber of the silent; Ketubot 67b:12-18); THE FOUR GRADES a DATA row (the_four_grades — 117:8); the exam\'s person the one who gives in secret in the chamber of the silent — accepted')
        return out("the secret gift (15:10) — 'give, you shall give him and your heart shall not grieve': the chamber of the silent (Mishnah Shekalim 5:6 inside the spine — the Sifrei 117:7), the secret givers (Ketubot 67b:12-18); the four grades of the giver (117:8): the one who gives in secret in the chamber of the silent accepted", ['accepted'])
    if ask == 'the_blessing_on_the_work':
        ink('15:10', '"for BECAUSE OF THIS THING the LORD your God will BLESS YOU IN ALL YOUR WORK AND IN ALL YOU PUT YOUR HAND TO" — "because of this thing" %s (one seat); "all that you put your hand to" the book\'s six %s; 14:29\'s twin "in all the work of your hand" %s, the shared run %d; the six blessings in five verses %s' % (P('בגלל', 'הדבר', 'הזה'), U('משלח', books=DT), P('בכל', 'מעשה', 'ידך', books=DT), TWIN['15:10 vs 14:29'], {v: [x for x in W15(v) if x in ('ברך', 'יברכך', 'ברכך', 'וברכך')] for v in range(1, 24) if any(x in ('ברך', 'יברכך', 'ברכך', 'וברכך') for x in W15(v))}))
        move('the Sifrei 117:9-10 (read whole at the reading); cold_run_food_tithe (CALL) — FT.the_third_year(the_four_in_want) = %s; the one database: work_of_the_hand_blessed anywhere before this sitting %s (14:29\'s line wrote none — the registry held no name at the types step)' % (str(V(FT_FOUR))[:40], HOLE_SCAN), "THE BLESSING ON THE WORK OF THE HAND — 'because of this thing': even if he said 'I will give' and did not give, even if he gave and it was lost, the blessing on the resolve (117:9-10); 'in all your work and in all you put your hand to' 14:29's twin (six tokens in order — the third year's tithe on the tape, third_year_tithe_declared, food_tithe by CALL): work_of_the_hand_blessed A NEW HEAVEN ENTRY at 15:10, its second seat at 15:18 (the blessing beside every money loss, 123:3); 14:29's line wrote no such name — measured at the types step, the design's 'or three' the one arm")
        dat('THE WRITE work_of_the_hand_blessed — a HEAVEN entry on israel_people at the counter\'s day (DG2 — TWO: 15:10\'s on the line hand_opening_commanded and 15:18\'s on hebrew_slave_law_declared); the readback row 15:10 SUPPLIED with the write, 14:29\'s line by kind; the exam\'s person the one who resolved to give and lost the coin — blessed on the resolve: accepted')
        return out("the blessing on the work (15:10) — 'because of this thing the LORD will bless you in all your work': even the resolve that was not fulfilled (the Sifrei 117:9-10); 14:29's twin six tokens in order (food_tithe by CALL, the tape's third_year_tithe_declared): THE WRITE work_of_the_hand_blessed, a HEAVEN entry on Israel — twice, 15:10 and 15:18; the one who resolved to give and lost the coin accepted", ['work_of_the_hand_blessed'])
