def the_hebrew_slave(case, data):
    """F4 — Deut 15:12-15 — THE THREE CASES each twin law its own (the court's sale here); the term SIX YEARS by CALL to mishpatim's clock (goes_free the fire), the woman ADDED with her exits by CALL to mishpatim_3; THE LINE hebrew_slave_law_declared writing furnishing_commanded (a STATUS) and empty_sending_barred (a BLOCK); severance_gift_owed the case's DEBIT priced by CALL to erection.repeats; Egypt the model; the memory 15:15 the one narrative verb — a REFERENCE row"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_three_cases':
        ink('15:12', '"if your brother, A HEBREW MAN OR A HEBREW WOMAN, BE SOLD to you" — "be sold" the niphal the Torah\'s seven %s (Leviticus 25\'s five, 27:28); Exodus 21:2 "when you BUY a Hebrew slave" %s, Leviticus 25:39 "and he be sold to you" %s; "Hebrew" the Torah\'s %d tokens, Abram the first' % ([(s, x) for s, x, m in LEMT('4376', books=T) if m and 'HVN' in m], words('Exod', 21, 2)[:4], words('Lev', 25, 39)[:6], len(LEMT('5680', books=T))))
        move('the Sifrei 118:4 (read whole at the reading); Kiddushin 14b:7-15b:4 (read whole at the docket); cold_run_mishpatim (CALL) — the F1 table %s; cold_run_yovel (CALL) — YO.hebrew_slave(israelite, 60, 20, 6) status = %s, exit = %s' % ([r[0] for r in MP_F1], V(YO_SLAVE['status']), str(V(YO_SLAVE['exit']))[:30]), "THE THREE CASES, EACH TWIN LAW ITS OWN — Exodus 21:2 the buyer's, Leviticus 25:39 the self-seller's, 15:12 THE COURT'S SALE (118:4 — 'your brother … be sold to you': by the court for his theft); Kiddushin 14b:7-15b:4 the sugya: the analogy 'hired worker'/'hired worker' (I2, checked in MIDDOT.md — Leviticus 25:40 with 15:18) joins the self-seller to the court's sale; the baraita's FOUR DIFFERENCES (14b:9-11 — the term six or more, the awl, the severance, the Canaanite maidservant) against R. Elazar's 'no difference'; the teacher who rejects the analogy is Rabbi (15a:23-15b:4); THE SALE'S ROAD THE VARIABLE — the cell's ask")
        dat('the three cases a DATA row (the_three_cases — the buyer\'s, the self-seller\'s, the court\'s; Kiddushin 14b:9-11 the four differences); the exam\'s person the thief sold by the court — serves six years and goes free: goes_free (mishpatim\'s status REUSED at the case)')
        return out("the three cases (15:12) — Exodus 21:2 the buyer's, Leviticus 25:39 the self-seller's, 15:12 the court's sale (the Sifrei 118:4; Kiddushin 14b:7-15b:4 — 'hired'/'hired' joins them, the four differences, Rabbi's dissent): the thief sold by the court serves six years and goes free", ['goes_free'])
    if ask == 'the_six_years_by_the_clock':
        ink('15:12', '"he shall serve you SIX YEARS and in the SEVENTH YEAR you shall send him away free" — the parser\'s [6] at 15:12 and 15:18 %s; "six years" the Torah\'s four %s (Exodus 21:2, Leviticus 25:3); Exodus 21:2\'s [6] %s; Jeremiah 34:14 quotes the verse — the shared run %d against Exodus 21:2\'s %d' % ([PARSED[(15, 12)], PARSED[(15, 18)]], SIX_YEARS, KINNUM[('Exod', 21, 2)], TWIN['15:12 vs Jer 34:14'], TWIN['15:12 vs Exod 21:2']))
        move('cold_run_mishpatim (CALL) — the F1 row %s (term_clock, goes_free); the wrap\'s scene tuple %s; cold_run_mishpatim_3 (CALL) — M3.maidservant(the_two_exits) = %s' % (MP_F1[0], MP_WRAP[:4], V(M3_TWO)), "THE TERM CLOCK IS EXODUS 21'S — 'six years' by CALL to mishpatim's F1 'slave-release: FREE-YEAR-7' (term_clock, goes_free: the same date six years on; the wrap's scene 'Kiddushin 1:2 — years, then the buy-out CANCELS the year-7 timer'); Jeremiah 34:14 THE RUN'S CASE quotes 15:12 (seven of fifteen in order) closer than Exodus 21:2 (three): the two verses of this chapter in one of his; NO TIMER ON THE TAPE — the term the case world's")
        dat('the six years by the clock a DATA row (the_six_years_by_the_clock — mishpatim\'s F1 by CALL; Jeremiah 34:14 the run\'s case, the closest kin by computation); the exam\'s person the slave bought in the first year — goes free in the seventh, the same date six years on: goes_free')
        return out("the six years by the clock (15:12) — 'he shall serve you six years and in the seventh go free': mishpatim's F1 term clock by CALL (FREE-YEAR-7 — term_clock, goes_free); Jeremiah 34:14 the run's case quotes the verse (seven of fifteen in order): the slave bought in the first year goes free in the seventh, the same date six years on", ['goes_free'])
    if ask == 'the_woman_added':
        ink('15:12', '"a Hebrew man OR A HEBREW WOMAN" — "the Hebrew woman" bare ONE seat %s (Jeremiah 34:9 with the vav); "or" twice in the chapter %s; Exodus 21:7 "she shall not go out as the menservants do" %s; Onkelos "a son of Israel or a daughter of Israel"' % (U('העבריה', 'עבריה'), {v: W15(v).count('או') for v in range(1, 24) if 'או' in W15(v)}, words('Exod', 21, 7)[-4:]))
        move('the Sifrei 118:5 (read whole at the reading); Mishnah Kiddushin 1:2 (inside the spine and at the docket); Kiddushin 14b:2-8, 16a:2-13, 18a:5-6 (read whole at the docket); cold_run_mishpatim_3 (CALL) — M3.maidservant(exits) = %s, (redemption) = %s, (who_sells) = %s' % (V(M3_EXITS), V(M3_REDEEM), V(M3_SELLS)), "THE WOMAN ADDED AGAINST EXODUS 21:7 — 'a Hebrew man or a Hebrew woman': the maidservant's exits BY CALL to mishpatim_3 (Mishnah Kiddushin 1:2: the Hebrew maidservant acquires herself by years, by the jubilee, by deduction and by the SIGNS beyond him — 'she shall not go out as the menservants do', 21:7, not by the tooth and the eye); redeemed against his will (Kiddushin 18a:5 — the cell citing Deut 15:12 already); the modes' grounds (14b:3-8 money from the gentile's sale and the maidservant's redemption; 16a:2-8 the document; no possession 16a:5); THE DEDUCTION AND THE BODY OWNED (Rava 16a:13); the two tables of 18a:5 with Rav Sheshet's designated maidservant (18a:6)")
        dat('the woman added a DATA row (the_woman_added — the maidservant\'s exits by CALL; 118:5; Kiddushin 14b-18a); the exam\'s person the Hebrew maidservant at her signs — goes out free: goes_free')
        return out("the woman added (15:12) — 'a Hebrew man or a Hebrew woman' against Exodus 21:7: the maidservant's exits by CALL to mishpatim_3 (Mishnah Kiddushin 1:2 — years, the jubilee, deduction, the signs; the Sifrei 118:5; Kiddushin 14b-18a): the Hebrew maidservant at her signs goes out free", ['goes_free'])
    if ask == 'the_exits_tables':
        ink('15:12', '"in the seventh year you shall send him away FREE from you" — "free" the chapter\'s three %s of seventeen in the Bible (Exodus 21\'s four; Jeremiah 34\'s six; Job\'s two; the Psalm\'s one); "from you" at 15:12, 13, 16, 18' % ([(s, x) for s, x, _ in LEMT('2670') if s.startswith('Deut 15')],))
        move('the Sifrei 118:5 (read whole at the reading); Mishnah Kiddushin 1:2 (read whole at the docket); Kiddushin 16b:3-8, 16b:17-18, 16a:14-16b:10, 20a:9-12, 20b:4-9 (read whole at the docket); cold_run_mishpatim_3 (CALL) — M3.maidservant(the_three) = %s, (these_three) = %s' % (V(M3_THREE), V(M3_THESE)), "THE MAN'S AND THE WOMAN'S EXITS TWO TABLES — the man by years, by the jubilee, by deduction of money (Mishnah Kiddushin 1:2); the woman by these and by the signs (118:5); THE FOUR WAYS with severance, three and three (16b:3-8, 16b:17-18); Reish Lakish's father's-death exit refuted (16a:14-16b:10); THE DEDUCTION'S PRICE the lower reckoning (20a:9-12, 20b:4-6 'expounded like Sinai'), no partial redemption (20b:8-9); the maidservant's three (food, clothing, conjugal right) and the master's these three (designate for himself, for his son, or redeem) by CALL")
        dat('the exits\' tables a DATA row (the_exits_tables — the two lists of Mishnah Kiddushin 1:2; the four ways with severance; the deduction\'s lower reckoning); the exam\'s person the slave who redeems himself by deduction at the lower reckoning — accepted')
        return out("the exits' tables (15:12) — the man by years, the jubilee and deduction, the woman by these and the signs (Mishnah Kiddushin 1:2; the Sifrei 118:5; Kiddushin 16a-16b the modes' grounds, 20a-20b the deduction's lower reckoning): a DATA row of the two lists; the slave who redeems himself by deduction at the lower reckoning accepted", ['accepted'])
    if ask == 'the_fugitive':
        ink('15:12', '"he shall serve you six years" — the verb "serve" %s (15:12, 15:18); the chapter\'s "serve" tokens %s' % ([x for x in W15(12) if x.startswith('ועבד')], [(v, x) for v in range(1, 24) for x in W15(v) if x.startswith(('ועבד', 'תעבד', 'עבד')) and v in (12, 17, 18, 19)]))
        move('the Sifrei 118:7 (read whole at the reading); Kiddushin 16b:21-17a:4 (read whole at the docket)', "THE FUGITIVE OWES HIS YEARS — 'he shall serve you six years': the one who fled and returned completes his six (118:7; Kiddushin 16b:21-17a:1); the fugitive excluded from the severance too ('from you' — 16b:20)")
        dat('the fugitive a DATA row (the_fugitive_and_the_sick — 118:7; Kiddushin 16b:21-17a:4); the exam\'s person the fugitive who returns — owes his years: accepted')
        return out("the fugitive (15:12) — 'he shall serve you six years': the one who fled completes his six (the Sifrei 118:7; Kiddushin 16b:21-17a:1), and takes no severance ('from you', 16b:20): the fugitive who returns accepted — he owes his years", ['accepted'])
    if ask == 'the_sick_slave':
        ink('15:12', '"six years … and in the seventh" — the two numbers of the verse %s; "double the hire of a hireling" at 15:18 the term\'s measure' % (PARSED[(15, 12)],))
        move('the Sifrei 118:7 (read whole at the reading); Kiddushin 17a:1-4 (read whole at the docket)', "THE SICK MAN NOT — the slave sick four years goes free at six and makes nothing up (118:7; Kiddushin 17a:1-2: sick four years as six; needlework no completion 17a:3-4 — the one who can do light work completes)")
        dat('the sick slave a DATA row (the_fugitive_and_the_sick); the exam\'s person the slave sick four of the six years — exempt from making them up')
        return out("the sick slave (15:12) — the slave sick four years goes free at six and makes nothing up (the Sifrei 118:7; Kiddushin 17a:1-4 — needlework no completion): the slave sick four of the six years exempt from making them up", ['exempt'])
    if ask == 'the_three_sendings':
        ink('15:12-13, 15:18', '"you shall SEND him away free" (15:12), "and when you SEND him away free from you, you shall not SEND him away empty" (15:13), "when you SEND him away free" (15:18) — the verb\'s tokens %s' % ([(v, x) for v in (12, 13, 18) for x in W15(v) if 'שלח' in x],))
        move('the Sifrei 119:1 (read whole at the reading); Kiddushin 16b:17-20 (read whole at the docket)', "THE THREE SENDINGS THE GIFT'S CASES — from the verb said three times: the one sent by years, the one sent by the jubilee, the one sent by the master's death (119:1); THE SELF-REDEEMER OUT ('when you send him' — not the one who redeems himself by deduction: 119:1; Kiddushin 16b:17-18 with R. Meir's arm), the fugitive out ('from you' 16b:20), the sendings extended by 'you shall not send' and 'when you send' (16b:19)")
        dat('the three sendings a DATA row (the_three_sendings — the verb said three times, the gift\'s cases; the self-redeemer out); the exam\'s person the master whose slave redeemed himself by deduction — exempt from the gift')
        return out("the three sendings (15:12-13, 15:18) — the verb said three times: by years, by the jubilee, by the master's death the gift's cases; the self-redeemer and the fugitive out (the Sifrei 119:1; Kiddushin 16b:17-20): the master whose slave redeemed himself by deduction exempt from the gift", ['exempt'])
    if ask == 'the_gifts_persons':
        ink('15:14', '"furnish, you shall furnish HIM … you shall give HIM" — "to him" twice %s; "furnish" the verb\'s ONE seat in the Torah %s (the Psalm\'s "chain" the homograph)' % ([x for x in W15(14) if x == 'לו'], [(s, x) for s, x, _ in LEMT('6059')]))
        move('the Sifrei 119:3 (read whole at the reading); Kiddushin 15a:6-7, 16b:11-16 (read whole at the docket)', "NOT TO HIS HEIRS — 'to him': to him and not to his heirs (119:3; Kiddushin 15a:7 — a hired worker's wage passes, the gift does not); not the self-seller (15a:6), not his creditor (Tutai 16b:16); THE MAIDSERVANT'S GIFT to her father while he lives (16b:11-13), her brothers excluded (16b:14)")
        dat('the gift\'s persons a DATA row (the_gifts_persons — to him not his heirs; not the self-seller; not his creditor; the maidservant\'s to her father); the exam\'s person the master of the dead slave — exempt from the gift to the heirs')
        return out("the gift's persons (15:14) — 'to him', not his heirs (the Sifrei 119:3; Kiddushin 15a:7), not the self-seller (15a:6), not his creditor (16b:16); the maidservant's gift to her father (16b:11-14): the master of the dead slave exempt from the gift to the heirs", ['exempt'])
    if ask == 'the_gift_feature':
        ink('15:14', '"from your FLOCK, your FLOOR and your PRESS" — the three nouns %s; "your floor and your press" 16:13\'s Sukkot %s; the verse has NO KIN BY COMPUTATION %s' % (W15(14)[3:6], P('מגרנך', 'ומיקבך'), KINC[14]))
        move('the Sifrei 119:4 (read whole at the reading); Kiddushin 17a:16-17b:3 (read whole at the docket)', "ONLY WHAT RESEMBLES THE PARTICULAR — fit for a blessing or bearing young (119:4 — I6's shape, checked in MIDDOT.md: the general 'that with which the LORD has blessed you', the particular the flock, the floor, the press): A DISPUTE the_gift_feature — the category of blessing: money out (R. Shimon), mules out (R. Eliezer ben Yaakov) — Kiddushin 17a:16-17b:1; 'grant, you shall grant' in any case (17b:2) against R. Elazar ben Azarya's plain reading ('the Torah speaks in the language of men', 17b:3)")
        dat('THE PARAMETER the_gift_feature (119:4 — I6\'s shape; Kiddushin 17a:16-17b:3 two arms); the exam\'s person the master who gives mules — accepted on R. Shimon\'s arm (money out), R. Eliezer ben Yaakov\'s recorded')
        return out("the gift's feature (15:14) — only what resembles the particular, fit for a blessing or bearing young (the Sifrei 119:4 — I6's shape): money out (R. Shimon), mules out (R. Eliezer ben Yaakov) — Kiddushin 17a:16-17b:3: THE PARAMETER the_gift_feature; the master who gives mules accepted on R. Shimon's arm", ['accepted'])
