    if ask == 'the_blemished_in_the_gates':
        ink('15:22', '"WITHIN YOUR GATES you shall eat it, THE UNCLEAN AND THE CLEAN ALIKE, AS THE GAZELLE AND AS THE HART" — the verse %s; 12:15\'s "the unclean and the clean … as the gazelle and as the hart" %s, 12:22 "as the gazelle and the hart is eaten, so you shall eat it, the unclean and the clean alike" %s: THE CLAUSE\'S THREE SEATS %s; "within your gates you shall eat it" %s (one seat); "in your gates" in the chapter %s' % (W15(22), words('Deut', 12, 15)[-5:], words('Deut', 12, 22)[-6:], UNCLEAN_CLEAN, P('בשעריך', 'תאכלנו'), [v for v in range(1, 24) if 'בשעריך' in W15(v)]))
